let store = MemoryStore::default();               // or SqliteStore / Redis store
let layer = SessionManagerLayer::new(store)
    .with_secure(true)
    .with_expiry(Expiry::OnInactivity(Duration::minutes(30)));

let app = Router::new().route("/cart", get(handler)).layer(layer);

async fn handler(session: Session) -> impl IntoResponse {
    let count: usize = session.get("count").await.unwrap().unwrap_or(0);
    session.insert("count", count + 1).await.unwrap();
    format!("count {}", count + 1)
}
